// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// StreamBrowserEvents The dashboard's live updates (ADR-0059 Decision 4): server-sent events, served only when /v1/meta lists the capability realtime.sse. The browser's session (its varlatch_session cookie) authenticates the stream; a stream receives the changeSignal of each Organization its identity is a member of when the signal is sent, and its own identity's identitySignal, never another's. Signals carry the domains an audit event touched and the last event's id, never data. Events: "ready" once, data {"identityId"}; "change", data {"organizationId", "lastEventId", "occurredAt", "domains"}; "identity", data {"lastEventId", "occurredAt", "domains"}; a comment line about every 15 s to keep the connection alive; and "close", data {"reason"}, as the server ends the stream: "session-ended" (signed out, expired, or the identity disabled), "credential-revoked" (a credential of the session revoked), "membership-removed" (after the identity event that says so), "slow-client" (16 publications waiting for it; a publication is the events one round of publishing sends it), "replaced" (more than 8 streams for one session; the oldest closes) or "shutdown". Once the server ends a stream, nothing it had queued is sent: only a removal's identity event and the close event, within 2 s. Nothing is replayed and no event carries an id: a dashboard that reconnects refreshes from /v1. 401 AUTHENTICATION_REQUIRED without a live session; 400 VALIDATION_FAILED, the connection closed, for a request that declares a body. Cache-Control no-store.
	// (GET /auth/events)
	StreamBrowserEvents(ctx context.Context, request StreamBrowserEventsRequestObject) (StreamBrowserEventsResponseObject, error)
	// FinishPasskeyRegistration Verify the registration and store the passkey. An enrollment consumes its setup grant, records the passkey as trusted (ADR-0054 Decision 4) and starts a session; a passkey a signed-in person adds is unconfirmed. A credential id already registered, for anyone, answers 400 PASSKEY_ALREADY_REGISTERED, before the grant is consumed.
	// (POST /auth/passkey/registration)
	FinishPasskeyRegistration(ctx context.Context, request FinishPasskeyRegistrationRequestObject) (FinishPasskeyRegistrationResponseObject, error)
	// StartPasskeyRegistration Start registering a passkey. With a setup token (an enrollment link's bootstrap, recovery, invitation or re-enrollment grant) the grant is checked, not consumed: a cancelled prompt leaves it usable until it expires. Without one the browser's session adds a passkey to its person. The person's passkeys are excluded.
	// (POST /auth/passkey/registration/options)
	StartPasskeyRegistration(ctx context.Context, request StartPasskeyRegistrationRequestObject) (StartPasskeyRegistrationResponseObject, error)
	// FinishPasskeySignIn Verify the sign-in assertion and start a session (the varlatch_session cookie), recording the sign-in's evidence (ADR-0054 Decision 6): which passkey asserted and whether it verified the user. The passkey's signature counter only moves forward. A passkey this server does not hold answers 400 PASSKEY_NOT_FOUND, so the browser may forget it.
	// (POST /auth/passkey/sign-in)
	FinishPasskeySignIn(ctx context.Context, request FinishPasskeySignInRequestObject) (FinishPasskeySignInResponseObject, error)
	// StartPasskeySignIn Start a passkey sign-in with a discoverable credential: WebAuthn request options naming no credential, user verification preferred. The challenge is bound to this browser's CSRF cookie and lasts 5 minutes.
	// (POST /auth/passkey/sign-in/options)
	StartPasskeySignIn(ctx context.Context, request StartPasskeySignInRequestObject) (StartPasskeySignInResponseObject, error)
	// GetBrowserSession The browser's session, if any, and its CSRF token (set as the varlatch_csrf cookie when the browser has none). Cache-Control no-store.
	// (GET /auth/session)
	GetBrowserSession(ctx context.Context, request GetBrowserSessionRequestObject) (GetBrowserSessionResponseObject, error)
	// SignOut End the browser's session: its browser bearers are revoked with it, and the CLI credentials of a browser hand-off are not. The cookie is cleared.
	// (POST /auth/sign-out)
	SignOut(ctx context.Context, request SignOutRequestObject) (SignOutResponseObject, error)
	// MintBrowserBearer Exchange the browser's session for a short-lived opaque /v1 bearer (ADR-0018 §6; never a JWT): 15 minutes, never past the session's end, revoked when the session ends. 401 AUTHENTICATION_REQUIRED without a live session. Cache-Control no-store.
	// (POST /auth/varlatch-token)
	MintBrowserBearer(ctx context.Context, request MintBrowserBearerRequestObject) (MintBrowserBearerResponseObject, error)
}

